+package com.example.customers.domain;
+
+import java.text.Normalizer;
+import java.util.EnumSet;
+import java.util.Locale;
+import java.util.Set;
+
+/**
+ * Filter applied by {@link CustomerRepository}.
+ *
+ * @param name     whitespace-separated terms; each must occur in first or last name
+ * @param statuses allowed statuses; empty means all
+ */
+public record CustomerFilter(String name, Set<CustomerStatus> statuses) {
+
+    public static final CustomerFilter EMPTY = new CustomerFilter("", Set.of());
+
+    public CustomerFilter {
+        name = name == null ? "" : name.strip();
+        statuses = (statuses == null || statuses.isEmpty())
+                ? Set.of() : Set.copyOf(EnumSet.copyOf(statuses));
+    }
+
+    public boolean matches(Customer customer) {
+        if (!statuses.isEmpty() && !statuses.contains(customer.status())) {
+            return false;
+        }
+        if (name.isEmpty()) {
+            return true;
+        }
+        String first = fold(customer.firstName());
+        String last = fold(customer.lastName());
+        for (String term : fold(name).split("\\s+")) {
+            if (!term.isEmpty() && !first.contains(term) && !last.contains(term)) {
+                return false;
+            }
+        }
+        return true;
+    }
+
+    static String fold(String s) {
+        return Normalizer.normalize(s, Normalizer.Form.NFD)
+                .replaceAll("\\p{M}+", "")
+                .toLowerCase(Locale.ROOT);
+    }
+}
